# Apply replacements
for line_num, new_content in sorted(replacements.items(), reverse=True):
    idx = line_num - 1  # 0-based
    old_line = lines[idx]
    if old_line.strip() != 'sorry':
        print(f'WARNING: Line {line_num} is not a sorry: {old_line!r}')
        continue
    # Replace the line with the new content
    # The new content should be indented with 2 spaces
    indented = '\n'.join('  ' + line if line else '' for line in new_content.split('\n'))
    # But the first line should keep the original indentation
    # Actually, the new_content already includes the indentation
    lines[idx] = new_content
    print(f'Replaced line {line_num}')

with open('lvFormal/Theory/LvDSL.lean', 'w') as f:
    f.writelines(lines)

print('Done')
